async function confirm({ key, kind, docId, messageId, ts, body, statusCode }, ctx) {
  const s = await ctx.state.get(key);
  if (!s || s.phase !== kind) throw Error("Missing matching phase");
  if (kind === "answer") {
    const calls =
      body?.output?.filter((x) => x.type === "file_search_call" && x.status === "completed") || [];
    const answer = (body?.output || [])
      .filter((x) => x.type === "message")
      .flatMap((x) => x.content || [])
      .filter((x) => x.type === "output_text")
      .map((x) => x.text)
      .join("\n");
    if (statusCode !== 200 || body?.status !== "completed" || !calls.length || !answer.trim())
      throw Error("Invalid file search response");
    s.answer = answer;
    s.phase = "append";
  } else {
    if (!s.pending) throw Error("Missing pending write");
    if (kind === "create") {
      if (!docId) throw Error("Unknown document creation");
      s.docId = docId;
      s.phase = "answer";
    } else if (kind === "append") {
      if (docId !== s.docId) throw Error("Unknown document update");
      s.index++;
      s.answer = "";
      s.phase = s.index < s.questions.length ? "answer" : "email";
    } else if (kind === "email") {
      if (!messageId) throw Error("Unknown email result");
      s.phase = "slack";
    } else if (kind === "slack") {
      if (!ts) throw Error("Unknown Slack result");
      s.phase = "done";
    }
    s.pending = null;
  }
  await ctx.state.set(key, s);
  return { ok: true };
}

export default async function f(input, ctx) {
  return confirm({ ...input, kind: "create" }, ctx);
}

